// Generated by Skyramp v1.3.44 on 2026-09-12
// Scenario: /home/runner/work/eval-linkwarden/eval-linkwarden/apps/web/e2e/scenario_preferences_rejects_revoked_session.json
//
// Every other /api/v1 route runs through apps/web/lib/api/verifyToken.ts, which refuses a
// credential whose accessToken row is revoked. A session the user revoked must therefore stop
// reading preferences too.
//
// This test is expected to FAIL on step 5 until the new handler routes through verifyToken
// (or repeats its revocation check): it calls next-auth's getToken directly and never consults
// accessToken.revoked, so a revoked session still reads the preference payload. Step 4 is the
// control — the same revoked cookie on /api/v1/users/me is already refused with 401.

// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import {
    SESSION_COOKIE,
    createSession,
    getTokens,
    deleteToken,
    getUsersMe,
    getUserPreferences,
} from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    // Unique per run so the lookup in step 2 finds this run's session and no other.
    const sessionName = uniqueSuffix("skyramp-prefs-revoked");

    // Step 1 — create a NextAuth session for the test user.
    const sessionPostResponse = await createSession(client, URL_localhost, sessionName);

    expect(sessionPostResponse.statusCode, 'status code').toBe(200);

    const sessionToken = getResponseValue(sessionPostResponse, "response.token");
    expect(typeof sessionToken, 'session token is a string').toBe("string");
    expect(sessionToken.length, 'session token is not empty').toBeGreaterThan(0);
    expect(sessionToken, 'session token is a JWE the NextAuth secret produced').toMatch(/^ey[\w-]+\.{2}/);

    const sessionAuth = {cookies: {[SESSION_COOKIE]: sessionToken}};

    // Step 2 — find that session in the caller's non-revoked token list.
    const tokensGetResponse = await getTokens(client, URL_localhost, sessionAuth, 200);

    expect(tokensGetResponse.statusCode, 'status code').toBe(200);

    const tokens = getResponseValue(tokensGetResponse, "response");
    expect(Array.isArray(tokens), 'token list is an array').toBe(true);
    const createdSession = tokens.find((t: any) => t.name === sessionName);
    expect(createdSession, `the session named ${sessionName} is listed while it is live`).toBeDefined();
    expect(createdSession.isSession, 'the credential under test is a session, not a personal access token').toBe(true);
    expect(createdSession.name, 'the listed session carries the name this test sent').toBe(sessionName);
    expect(createdSession.id, 'the listed session has a real id').toBeGreaterThan(0);
    expect(createdSession.expires, 'the listed session carries an ISO expiry').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    // Step 3 — revoke it. This is the state the request under test runs against.
    const tokensTokensDeleteResponse = await deleteToken(client, URL_localhost, createdSession.id, sessionAuth, 200);

    expect(tokensTokensDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(tokensTokensDeleteResponse, "response.revoked"), 'the session is now revoked').toBe(true);
    expect(getResponseValue(tokensTokensDeleteResponse, "response.id"), 'the revoked record is the session this test created').toBe(createdSession.id);
    expect(getResponseValue(tokensTokensDeleteResponse, "response.name"), 'the revoked record carries the name this test sent').toBe(sessionName);
    expect(getResponseValue(tokensTokensDeleteResponse, "response.isSession"), 'the revoked record is the session, not a personal access token').toBe(true);

    // Step 4 — control: the application does enforce revocation on its existing routes.
    const meGetResponse = await getUsersMe(client, URL_localhost, sessionAuth, 401);

    expect(meGetResponse.statusCode, 'status code').toBe(401);
    expect(getResponseValue(meGetResponse, "response"), 'the revoked session is told its session expired')
        .toBe("Your session has expired, please log in again.");

    // Step 5 — THE BEHAVIOUR UNDER TEST: the new endpoint must refuse the same revoked session.
    const preferencesGetResponse = await getUserPreferences(client, URL_localhost, sessionAuth, 401);

    expect(preferencesGetResponse.statusCode, 'a revoked session cookie is refused').toBe(401);
    expect(getResponseValue(preferencesGetResponse, "response.linksRouteTo"), 'no preference data leaks to a revoked session').toBeNull();
    expect(getResponseValue(preferencesGetResponse, "response.theme"), 'no theme preference leaks to a revoked session').toBeNull();
    expect(getResponseValue(preferencesGetResponse, "response.id"), 'no user id leaks to a revoked session').toBeNull();
});
